public int majorityElement(int[] nums) {
    Map<Integer, Integer> counts = new HashMap<>();
    int n = nums.length;
    for (int x : nums) {
        int c = counts.merge(x, 1, Integer::sum);
        if (c > n / 2) {
            return x;
        }
    }
    return -1; // unreachable: majority guaranteed
}

