def majorityElement(self, nums: list[int]) -> int:
    counts: dict[int, int] = {}
    n = len(nums)
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > n // 2:
            return x
    return -1  # unreachable: majority guaranteed

